const groups={sculpt:'EQ',prism:'EQ',balance:'EQ',glue:'Dynamique',press:'Dynamique',peak:'Dynamique',hush:'Voix',sibil:'Voix',exofocus:'Voix',color:'Saturation',ember:'Saturation',exoair:'Saturation',echo:'Delay',relay:'Delay',aura:'Réverbération',exospace:'Réverbération',orbit:'Modulation',sway:'Modulation',exostrip:'Channel strip'};
const key='warlike.plugin.favorites.v1',normal=s=>String(s).toLowerCase().normalize('NFD').replace(/\p{M}/gu,'');
export function pluginCategory(id,def){return groups[id]||({piano:'Pianos & claviers',upright:'Pianos & claviers',epiano:'Pianos & claviers',harp:'Cordes pincées',strum:'Cordes pincées',violin:'Cordes frottées',cello:'Cordes frottées',flute:'Vents',trumpet:'Vents',marimba:'Percussions mélodiques',vibes:'Percussions mélodiques',kalimba:'Percussions mélodiques',drums:'Batterie'})[id]||'Synthétiseurs';}
export function filterPluginChoices(registry,{query='',category='all',favorites=[],favoritesOnly=false}={}){const search=normal(query);return Object.entries(registry).filter(([id,def])=>(category==='all'||pluginCategory(id,def)===category)&&(!favoritesOnly||favorites.includes(id))&&normal(def.name+' '+def.subtitle+' '+pluginCategory(id,def)).includes(search));}
export function mountPluginPicker({root,registry,onChoose,selected=null,esc}){
 let favorites=[];try{const data=JSON.parse(localStorage.getItem(key));if(Array.isArray(data))favorites=data.filter(x=>typeof x==='string').slice(0,128);}catch{}
 const state={query:'',category:'all',favorites,favoritesOnly:false},host=document.createElement('section');host.className='plugin-picker';
 const categories=[...new Set(Object.entries(registry).map(([id,d])=>pluginCategory(id,d)))];host.innerHTML=`<div class="picker-search"><input id="pluginSearch" aria-label="Rechercher un plugin" placeholder="Rechercher un plugin…" autocomplete="off"><button id="pluginFavoritesOnly" class="outline-btn" aria-pressed="false">★ Favoris</button></div><div class="picker-categories"><button data-picker-category="all" class="chosen">Tous</button>${categories.map(c=>`<button data-picker-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div id="pluginPickerResults" class="picker-results"></div>`;root.prepend(host);
 const result=host.querySelector('#pluginPickerResults');function render(){const items=filterPluginChoices(registry,state);result.innerHTML=items.map(([id,d])=>`<div class="picker-row ${id===selected?'current':''}"><button data-picker-load="${id}" class="picker-choice"><strong>${esc(d.name)}</strong><span>${esc(d.subtitle)}</span><small>${esc(pluginCategory(id,d))}${d.pack?' · '+esc(d.pack.toUpperCase()):''}</small></button><button data-picker-favorite="${id}" class="picker-star" aria-label="Favori ${esc(d.name)}" aria-pressed="${state.favorites.includes(id)}">${state.favorites.includes(id)?'★':'☆'}</button></div>`).join('')||'<p class="picker-empty">Aucun plugin trouvé.</p>';}
 host.querySelector('input').oninput=e=>{state.query=e.target.value;render();};host.querySelector('#pluginFavoritesOnly').onclick=e=>{state.favoritesOnly=!state.favoritesOnly;e.currentTarget.setAttribute('aria-pressed',state.favoritesOnly);render();};
 host.onclick=e=>{const category=e.target.closest('[data-picker-category]');if(category){state.category=category.dataset.pickerCategory;host.querySelectorAll('[data-picker-category]').forEach(b=>b.classList.toggle('chosen',b===category));render();return;}const star=e.target.closest('[data-picker-favorite]');if(star){const id=star.dataset.pickerFavorite;state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];try{localStorage.setItem(key,JSON.stringify(state.favorites));}catch{}render();return;}const choice=e.target.closest('[data-picker-load]');if(choice)onChoose(choice.dataset.pickerLoad);};
 host.onkeydown=e=>{const buttons=[...result.querySelectorAll('[data-picker-load]')];if(!buttons.length)return;const i=buttons.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length].focus();}else if(e.key==='Enter'&&e.target.matches('input')){e.preventDefault();onChoose(buttons[0].dataset.pickerLoad);}};render();requestAnimationFrame(()=>host.querySelector('input').focus());return host;
}
